patch:
diff --git a/repro-no-var-tdz.js b/repro-no-var-tdz.js
new file mode 100644
index 0000000..661f2b6
--- /dev/null
+++ b/repro-no-var-tdz.js
@@ -0,0 +1,74 @@
+"use strict";
+/*
+ * Reproduction for "[no-var] Fix causes ReferenceError".
+ * Runs `no-var` autofix on each case, then executes the original and the fixed
+ * code. A case is a bug if the original runs fine but the fixed code throws a
+ * ReferenceError (TDZ) or changes behavior.
+ */
+const { Linter } = require("./lib/api");
+const vm = require("node:vm");
+
+const cases = {
+	"report (exact)": `function a() {
+    console.log(o);
+    var o;
+    return o;
+}
+a();`,
+	"hoisted fn passed as callback": `function a() {
+    [1].forEach(g);
+    var o;
+    function g() { return o; }
+}
+a();`,
+	"hoisted fn invoked via .call()": `function a() {
+    g.call(null);
+    var o;
+    function g() { return o; }
+}
+a();`,
+	"hoisted fn called transitively": `function a() {
+    h();
+    var o;
+    function h() { return g(); }
+    function g() { return o; }
+}
+a();`,
+	"hoisted fn called as tagged template": "function a() {\n    g``;\n    var o;\n    function g() { return o; }\n}\na();",
+	"hoisted fn called via new": `function a() {
+    new G();
+    var o;
+    function G() { return o; }
+}
+a();`,
+	"destructuring default refs later binding": `function a() {
+    var [x = y, y] = [];
+    return [x, y];
+}
+a();`,
+};
+
+const linter = new Linter({ configType: "flat" });
+const config = { rules: { "no-var": "error" }, languageOptions: { sourceType: "script" } };
+const run = code => {
+	try {
+		vm.runInNewContext(code, { console: { log() {} } });
+		return "ok";
+	} catch (e) {
+		return `${e.constructor.name}: ${e.message}`;
+	}
+};
+
+let bugs = 0;
+for (const [name, code] of Object.entries(cases)) {
+	const { output, fixed } = linter.verifyAndFix(code, config);
+	const before = run(code);
+	const after = run(output);
+	const bug = fixed && before === "ok" && after !== "ok";
+	if (bug) bugs++;
+	console.log(`=== ${name}: ${bug ? "BUG" : fixed ? "fixed, safe" : "not fixed (safe)"}`);
+	console.log(`  original runs: ${before}\n  fixed runs:    ${after}`);
+	if (fixed) console.log(output.replace(/^/gm, "    | "));
+}
+console.log(`\n${bugs} case(s) where the no-var autofix introduces a runtime error`);
+process.exitCode = bugs ? 1 : 0;
